  excerpt: "Moving to Vietnam? Visas for staying, where to live, money, health, work and your first month, with links to our detailed guides. Checked 27 October 2026.",
  metaTitle: "Living in Vietnam: A Practical Expat Guide 2026",
  metaDescription: "Moving to Vietnam? Visas for staying, where to live, money, health, work and your first month, with links to our detailed guides. Checked 27 October 2026.",
  breadcrumbName: "Living in Vietnam",
  inlineCtas: false,
  author: 'Vietnam Launchpad',
